function aq(ar, as) {
    var aK = ar['length'];
    var aL = (ar[(aK-0x1)]&0xffffffff);
    for (var aM = 0x0; (aM<aK); aM++) {
        ar[aM] = String['fromCharCode'](ar[aM] & 0xff, ((ar[aM]>>>0x8)&0xff), ((ar[aM]>>>0x10)&0xff),(ar[aM]>>>0x18) & 0xff);
    }
