var push = (title, url, size) => result.push({"title": title,"url": url,"style": {"layout_flexGrow": 1,"layout_flexBasisPercent": size}});
var tagUrl = "https://m.suixkan.com/l/f/0.html";
var tag = java.ajax(tagUrl);
var tagList = org.jsoup.Jsoup.parse(tag).select(".tab-bar .tab-item");
var childTagSize = 0.4;
for (var i in tagList) {
    var title = tagList[i].text();
    var url = source.key + String(tagList[i].attr("onclick")).replace(/gotoPage\('(.*?)'\)/, '$1');
    title = String(title).replace(/\s/g, "");
    push(title, null, 1);
    var childTag = java.ajax(url);
    var childTagList = org.jsoup.Jsoup.parse(childTag).select(".ca-con .ca-item");
    for (var j in childTagList) {
        var childTitle = childTagList[j].text();
        var childUrl = source.key + String(childTagList[j].attr("onclick")).replace(/gotoPage\('(.*?)(\d+.html)'\)/, '$1') + `{{page}}.html`;
        childTitle = String(childTitle).replace(/\s/g, "");
        push(childTitle, childUrl, childTagSize);
    }
    var spaceLength = childTagList.length % 2;
    for (q = 0; q < spaceLength; q++) {
        push("————",null,childTagSize);
    }
}
JSON.stringify(result);

